		"geometry_before": geometry_count(), "source_host_modified": false}
	match settings.kind:
		"grass": setup_grass()
		"water": setup_water()
		"bistro": setup_bistro()
		"fps": setup_fps()
		"forest": setup_forest()
	report.geometry_after = geometry_count()
	report.targets = settings.targets
