	var position: Array = keys[-1].position_xz_m
	for i in range(keys.size()-1):
		if time <= float(keys[i+1].time_s):
			var alpha := clampf((time-float(keys[i].time_s))/(float(keys[i+1].time_s)-float(keys[i].time_s)),0,1)
